export class Table { constructor() { this.m = new Map(); this.hdr = false } }
export class Arr { constructor(aot) { this.items = []; this.aot = aot } }
export class Scal { constructor(t, v) { this.t = t; this.v = v } }

class ConfError extends Error {
  constructor(msg) { super(msg); this.confError = true }
}
const fail = (m) => { throw new ConfError(m) }

const isWs = (c) => c === ' ' || c === '\t'
const isNameCh = (c) => c !== undefined && /^[A-Za-z0-9_-]$/.test(c)
const INT = /^[+-]?\d+(_\d+)*$/
const FLOAT = /^[+-]?\d+(_\d+)*(\.\d+(_\d+)*)?([eE][+-]?\d+(_\d+)*)?$/

class LineParser {
  constructor(s) { this.s = s; this.i = 0 }
  ws() { while (isWs(this.s[this.i])) this.i++ }
  /** True when at end of line or at a comment start. */
  eol() {
    const c = this.s[this.i]
    return c === undefined || c === '#' || c === ';'
  }
  quoted() {
    const q = this.s[this.i++]
    let out = ''
    for (;;) {
      const c = this.s[this.i]
      if (c === undefined) fail('unterminated string')
      this.i++
      if (c === q) return out
      if (q === '"' && c === '\\') {
        const e = this.s[this.i]
        if (e === undefined) fail('unterminated string')
        this.i++
        if (e === '"') out += '"'
        else if (e === '\\') out += '\\'
        else if (e === 'n') out += '\n'
        else if (e === 't') out += '\t'
        else if (e === 'r') out += '\r'
        else if (e === '0') out += '\0'
        else if (e === 'u') {
          const h = this.s.slice(this.i, this.i + 4)
          if (!/^[0-9a-fA-F]{4}$/.test(h)) fail('invalid escape \\u')
          out += String.fromCharCode(parseInt(h, 16))
          this.i += 4
        } else fail(`invalid escape \\${String.fromCodePoint(e.codePointAt(0))}`)
      } else out += c
    }
  }
  name() {
    const c = this.s[this.i]
    if (c === '"' || c === "'") return this.quoted()
    const st = this.i
    while (isNameCh(this.s[this.i])) this.i++
    if (st === this.i) fail('expected a name')
    return this.s.slice(st, this.i)
  }
  dotted() {
    const parts = [this.name()]
    for (;;) {
      const save = this.i
      this.ws()
      if (this.s[this.i] === '.') {
        this.i++
        this.ws()
        parts.push(this.name())
      } else { this.i = save; return parts }
    }
  }
  value(path, ctx) {
    const c = this.s[this.i]
    if (c === '"' || c === "'") return new Scal('string', this.quoted())
    if (c === '[') return this.array(path, ctx)
    if (c === '{') return this.inline(path, ctx)
    const st = this.i
    while (this.i < this.s.length && !isWs(this.s[this.i]) && !',]};'.includes(this.s[this.i])) {
      if (this.s[this.i] === '#' && this.i === st) break
      this.i++
    }
    const w = this.s.slice(st, this.i)
    if (w === '') fail('expected a value')
    if (w === 'true') return new Scal('boolean', true)
    if (w === 'false') return new Scal('boolean', false)
    if (INT.test(w)) return new Scal('integer', BigInt(w.replace(/_/g, '')))
    if (FLOAT.test(w)) return new Scal('float', Number(w.replace(/_/g, '')))
    fail(`invalid value ${w}`)
  }
  array(path) {
    this.i++
    const arr = new Arr(false)
    for (;;) {
      this.ws()
      if (this.eol()) fail('unterminated array')
      if (this.s[this.i] === ']') { this.i++; return arr }
      arr.items.push(this.value(`${path}[${arr.items.length}]`))
      this.ws()
      if (this.eol()) fail('unterminated array')
      const c = this.s[this.i]
      if (c === ',') this.i++
      else if (c === ']') { this.i++; return arr }
      else fail('unterminated array')
    }
  }
  inline(path) {
    this.i++
    const t = new Table()
    this.ws()
    if (this.eol()) fail('unterminated inline table')
    if (this.s[this.i] === '}') { this.i++; return t }
    for (;;) {
      this.ws()
      if (this.eol()) fail('unterminated inline table')
      const keys = this.dotted()
      this.ws()
      if (this.s[this.i] !== '=') fail('expected = in an inline table')
      this.i++
      this.ws()
      const v = this.value(path)
      assign(t, path, keys, v)
      this.ws()
      if (this.eol()) fail('unterminated inline table')
      const c = this.s[this.i]
      if (c === ',') this.i++
      else if (c === '}') { this.i++; return t }
      else fail('unterminated inline table')
    }
  }
}

const join = (base, k) => (base === '' ? k : `${base}.${k}`)

/** Step into the table at `key`, creating it; arrays of tables use their last element. */
function walk(t, base, key) {
  const p = join(base, key)
  let n = t.m.get(key)
  if (n === undefined) { n = new Table(); t.m.set(key, n) }
  if (n instanceof Table) return [n, p]
  if (n instanceof Arr && n.aot) return [n.items[n.items.length - 1], p]
  return fail(`${p} is not a table`)
}

function assign(t, base, keys, v) {
  let p = base
  for (let j = 0; j < keys.length - 1; j++) [t, p] = walk(t, p, keys[j])
  const last = keys[keys.length - 1]
  const full = join(p, last)
  if (t.m.has(last)) fail(`key ${full} is defined twice`)
  t.m.set(last, v)
}

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = new Table()
  let cur = root
  let curPath = ''
  for (let n = 0; n < lines.length; n++) {
    try {
      const lp = new LineParser(lines[n])
      lp.ws()
      if (lp.eol()) continue
      if (lp.s[lp.i] === '[') {
        const aot = lp.s[lp.i + 1] === '['
        lp.i += aot ? 2 : 1
        lp.ws()
        const keys = lp.dotted()
        lp.ws()
        for (let k = 0; k < (aot ? 2 : 1); k++) {
          if (lp.s[lp.i] !== ']') fail('unterminated table header')
          lp.i++
        }
        lp.ws()
        if (!lp.eol()) fail('trailing text after a table header')
        let t = root
        let p = ''
        for (let j = 0; j < keys.length - 1; j++) [t, p] = walk(t, p, keys[j])
        const last = keys[keys.length - 1]
        const full = join(p, last)
        const ex = t.m.get(last)
        if (aot) {
          if (ex === undefined) { const a = new Arr(true); t.m.set(last, a); cur = new Table(); a.items.push(cur) }
          else if (ex instanceof Arr && ex.aot) { cur = new Table(); ex.items.push(cur) }
          else fail(`${full} is not an array of tables`)
        } else {
          if (ex === undefined) { cur = new Table(); t.m.set(last, cur) }
          else if (ex instanceof Table) { cur = ex }
          else fail(`${full} is not a table`)
          if (cur.hdr) fail(`table ${full} is defined twice`)
          cur.hdr = true
        }
        curPath = full
        continue
      }
      const keys = lp.dotted()
      lp.ws()
      if (lp.s[lp.i] !== '=') fail('expected key = value')
      lp.i++
      lp.ws()
      const full = join(curPath, keys.join('.'))
      const v = lp.value(full)
      lp.ws()
      if (!lp.eol()) fail('trailing text after a value')
      assign(cur, curPath, keys, v)
    } catch (e) {
      if (e && e.confError) e.line = n + 1
      throw e
    }
  }
  return root
}
