cat > src/render.js <<'EOF'
import { Table, Arr } from './parser.js'

function cmp(a, b) {
  const x = Array.from(a, (c) => c.codePointAt(0))
  const y = Array.from(b, (c) => c.codePointAt(0))
  for (let i = 0; i < Math.min(x.length, y.length); i++) if (x[i] !== y[i]) return x[i] - y[i]
  return x.length - y.length
}
const sortedKeys = (t) => [...t.m.keys()].sort(cmp)

function json(n, ind) {
  if (n instanceof Table) {
    const ks = sortedKeys(n)
    if (!ks.length) return '{}'
    const pad = '  '.repeat(ind + 1)
    return `{\n${ks.map((k) => `${pad}${JSON.stringify(k)}: ${json(n.m.get(k), ind + 1)}`).join(',\n')}\n${'  '.repeat(ind)}}`
  }
  if (n instanceof Arr) {
    if (!n.items.length) return '[]'
    const pad = '  '.repeat(ind + 1)
    return `[\n${n.items.map((x) => pad + json(x, ind + 1)).join(',\n')}\n${'  '.repeat(ind)}]`
  }
  if (n.t === 'integer') return n.v.toString()
  return JSON.stringify(n.v)
}

export const renderJson = (root) => json(root, 0) + '\n'

export function renderKeys(root) {
  const out = []
  const visit = (n, p) => {
    if (n instanceof Table) {
      for (const k of sortedKeys(n)) {
        const q = p === '' ? k : `${p}.${k}`
        out.push(`${q} table`.replace(/ table$/, ` ${n.m.get(k) instanceof Table ? 'table' : n.m.get(k) instanceof Arr ? 'array' : n.m.get(k).t}`))
        visit(n.m.get(k), q)
      }
    } else if (n instanceof Arr) {
      n.items.forEach((x, i) => {
        const q = `${p}[${i}]`
        out.push(`${q} ${x instanceof Table ? 'table' : x instanceof Arr ? 'array' : x.t}`)
        visit(x, q)
      })
    }
  }
  visit(root, '')
  return out.length ? out.join('\n') + '\n' : ''
}
